    p.* = .{ .child = undefined, .alive = false, .pid = -1 };
    p.child = std.process.spawn(_io, .{
        .argv   = argv.items,
        .stdin  = .ignore,
        .stdout = .ignore,
        .stderr = .inherit,
    }) catch return p;
    p.alive = true;
    // pid: on POSIX child.id is pid_t; on Windows GetProcessId is not in Zig std so we leave -1.
    if (comptime builtin.os.tag != .windows) {
        if (p.child.id) |pid| p.pid = @intCast(pid);
    }
    return p;
}
pub fn _sys_process_kill(p: *_SysProcess) void {
    if (!p.alive) return;
    p.child.kill(_io);
    p.alive = false;
}
pub fn _sys_process_is_running(p: *_SysProcess) bool {
    if (!p.alive) return false;
    if (comptime builtin.os.tag == .windows) {
        const handle = p.child.id orelse { p.alive = false; return false; };
        var timeout: std.os.windows.LARGE_INTEGER = 0;
        const status = std.os.windows.ntdll.NtWaitForSingleObject(handle, .FALSE, &timeout);
        if (status == .TIMEOUT) return true;
        p.alive = false;
        return false;
    } else {
        const pid = p.child.id orelse { p.alive = false; return false; };
        const r = std.posix.waitpid(pid, std.posix.W.NOHANG);
        if (r.pid != 0) { p.alive = false; return false; }
        return true;
    }
}
pub fn _sys_readline() ?[]const u8 {
    const stdin = std.Io.File.stdin();
    var buf: [256]u8 = undefined;
    var rdr = stdin.readerStreaming(_io, &buf);
    var line: std.ArrayList(u8) = .empty;
    var byte_buf: [1]u8 = undefined;
    while (true) {
        const n = rdr.interface.readSliceShort(&byte_buf) catch return if (line.items.len > 0) line.items else null;
        if (n == 0) return if (line.items.len > 0) line.items else null;
        const b = byte_buf[0];
        if (b == '\n') break;
        if (b != '\r') line.append(_allocator, b) catch return null;
    }
    return line.items;
}
// Read EXACTLY `count` bytes from stdin (byte-at-a-time, no read-ahead so
// consecutive reads stay aligned — used for LSP Content-Length framing).
// Returns null at clean EOF; a short read at EOF returns what was read.
pub fn _sys_read_bytes(count: i64) ?[]const u8 {
    if (count <= 0) return "";
    const stdin = std.Io.File.stdin();
    var buf: [256]u8 = undefined;
    var rdr = stdin.readerStreaming(_io, &buf);
    var out: std.ArrayList(u8) = .empty;
    var byte_buf: [1]u8 = undefined;
    var i: i64 = 0;
    while (i < count) : (i += 1) {
        const n = rdr.interface.readSliceShort(&byte_buf) catch return if (out.items.len > 0) out.items else null;
        if (n == 0) return if (out.items.len > 0) out.items else null;
        out.append(_allocator, byte_buf[0]) catch return null;
    }
    return out.items;
}
